import sys
import csv
import json
import re


def normalize(name):
    """Collapse all whitespace runs to a single space, trim, then casefold."""
    return re.sub(r"\s+", " ", name).strip().casefold()


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py INPUT\n")
        return 2

    path = sys.argv[1]
    # Read-only access preserves the input file's bytes.
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        rows = list(csv.reader(f))

    if not rows:
        json.dump([], sys.stdout, ensure_ascii=False)
        return 0

    header = [h.strip().casefold() for h in rows[0]]
    try:
        item_idx = header.index("item")
        qty_idx = header.index("quantity")
    except ValueError:
        item_idx, qty_idx = 0, 1

    totals = {}
    for row in rows[1:]:
        if not row:
            continue
        while len(row) <= max(item_idx, qty_idx):
            row.append("")
        name = normalize(row[item_idx])
        if not name:
            continue
        qty_raw = row[qty_idx].strip()
        if qty_raw == "":
            qty = 1
        else:
            qty = int(qty_raw, 10)
        if qty < 0:
            # Contract guarantees nonnegative integers; skip invalid.
            continue
        totals[name] = totals.get(name, 0) + qty

    result = [{"item": k, "quantity": v} for k, v in sorted(totals.items())]
    json.dump(result, sys.stdout, ensure_ascii=False)
    return 0


if __name__ == "__main__":
    sys.exit(main())
